import json,sys,unittest
suite=unittest.TestSuite()
for pattern in ['test_writer_client_probe.py', 'test_client_write_catalog.py', 'test_client_writer_session.py', 'test_client_writer_owner.py', 'test_client_ledger.py', 'test_client_transport.py', 'test_native_preview.py', 'test_client_preview.py', 'test_client_writer_preview.py', 'test_client_writer_publication.py', 'test_publication_deadline.py', 'test_publication_profiles.py', 'test_publication_preview.py']:
    suite.addTests(unittest.defaultTestLoader.discover('tests/blender',pattern=pattern))
def flatten(value):
    for test in value:
        if isinstance(test,unittest.TestSuite):
            yield from flatten(test)
        else:
            yield test.id()
ids=list(flatten(suite))
print('GT04_WRITER_UNIT_INVENTORY '+json.dumps(ids),flush=True)
result=unittest.TextTestRunner(verbosity=2).run(suite)
counts={'run':result.testsRun,'failures':len(result.failures),'errors':len(result.errors),'skips':len(result.skipped)}
print('GT04_WRITER_UNIT_COMPLETE '+json.dumps(counts),flush=True)
sys.exit(not result.wasSuccessful())
